// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    RewardVault c;
    function setUp() public { c = new RewardVault(); }
    function testFuzz_property(uint256 depositAmount, uint256 newRate, address user) public {
        vm.assume(user != address(this) && user != c.owner());
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        newRate = bound(newRate, 0, type(uint128).max);

        c.setRewardRate(newRate);

        vm.deal(user, depositAmount);
        vm.prank(user);
        c.deposit{value: depositAmount}();

        uint256 balance = c.balance(user);
        uint256 expectedReward = balance * newRate;

        vm.prank(user);
        uint256 claimedReward = c.claim();

        assertEq(claimedReward, expectedReward, "reward is balance * rate at deposit");
    }
}
